                </p>
                <p class="status" id="status" aria-live="polite">${state.deleted ? 'Image deleted from your library.' : ''}</p>
              </div>

              ${PreviewCard()}
            </section>
          </main>
        </div>

        ${ConfirmDialog()}
      `;
    }

    function PreviewCard() {
      return `
        <article class="preview-card" aria-label="Image preview card" data-state="${state.deleted ? 'is-deleted' : 'active'}">
          <div class="image-frame">
            ${
              state.deleted
                ? `<div style="display:grid;place-items:center;height:100%;padding:2rem;background:linear-gradient(135deg,#dbeafe,#e0e7ff);text-align:center;">
                     <div>
                       <p style="margin:0;font-weight:700;font-size:1.15rem;">Image removed</p>
                       <p style="margin:0.5rem 0 0;color:#51607a;">This preview is no longer available.</p>
                     </div>
                   </div>`
                : `<img
                     src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1200 900'%3E%3Cdefs%3E%3ClinearGradient id='sky' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop offset='0%25' stop-color='%2380aefb'/%3E%3Cstop offset='55%25' stop-color='%23dbeafe'/%3E%3Cstop offset='100%25' stop-color='%23fff7ed'/%3E%3C/linearGradient%3E%3ClinearGradient id='sun' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop offset='0%25' stop-color='%23fde68a'/%3E%3Cstop offset='100%25' stop-color='%23fb923c'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1200' height='900' fill='url(%23sky)'/%3E%3Ccircle cx='902' cy='184' r='74' fill='url(%23sun)'/%3E%3Cpath d='M0 640 C180 560, 260 540, 420 590 S720 710, 900 650 S1080 570, 1200 615 L1200 900 L0 900 Z' fill='%23225878' opacity='0.85'/%3E%3Cpath d='M0 720 C210 650, 330 660, 500 720 S780 835, 980 770 S1110 700, 1200 725 L1200 900 L0 900 Z' fill='%231a365d' opacity='0.92'/%3E%3Cg opacity='0.25'%3E%3Ccircle cx='185' cy='220' r='88' fill='%23ffffff'/%3E%3Ccircle cx='270' cy='190' r='62' fill='%23ffffff'/%3E%3Ccircle cx='345' cy='225' r='76' fill='%23ffffff'/%3E%3C/g%3E%3C/svg%3E"
