          <div class="chip-row" aria-label="Image tags">
            <span class="chip">Landscape</span>
            <span class="chip">Featured</span>
            <span class="chip">Edited</span>
          </div>

          <div class="actions">
            <button type="button" class="btn btn-primary trigger" id="open-delete-dialog" aria-haspopup="dialog" aria-controls="confirm-delete-dialog">
              Delete image
            </button>
            <button type="button" class="btn btn-secondary">Download</button>
          </div>
        </article>
      `;
    }

    function ConfirmDialog() {
      return `
        <dialog id="confirm-delete-dialog" aria-labelledby="confirm-delete-title" aria-describedby="confirm-delete-copy">
          <div class="dialog-shell">
            <div class="dialog-head">
              <div class="dialog-icon" aria-hidden="true">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M12 8v5" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
                  <circle cx="12" cy="16.5" r="1" fill="currentColor"/>
                  <path d="M10.3 4.5h3.4L21 18.2A2 2 0 0 1 19.3 21H4.7A2 2 0 0 1 3 18.2L10.3 4.5Z" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>
                </svg>
              </div>
              <div>
                <h2 class="dialog-title" id="confirm-delete-title">Delete this image from your library?</h2>
                <p class="dialog-copy" id="confirm-delete-copy">
                  This removes the image from your library. You can only undo it if you still have a backup elsewhere.
                </p>
              </div>
            </div>

            <div class="dialog-actions">
              <button type="button" class="btn btn-secondary" data-dialog-close autofocus>Cancel</button>
              <button type="button" class="btn btn-danger" data-dialog-confirm>Delete</button>
            </div>
          </div>
        </dialog>
      `;
    }

    function render() {
      app.innerHTML = App();
      bindDialog();
    }

    function bindDialog() {
      const dialog = document.getElementById('confirm-delete-dialog');
      const trigger = document.getElementById('open-delete-dialog');
      const closeButton = dialog.querySelector('[data-dialog-close]');
      const confirmButton = dialog.querySelector('[data-dialog-confirm]');
      const status = document.getElementById('status');
      const imageFrame = document.querySelector('.image-frame');
      const previewCard = document.querySelector('.preview-card');

      trigger.addEventListener('click', () => {
        dialog.showModal();
      });

      closeButton.addEventListener('click', () => {
        dialog.close('cancel');
      });

      confirmButton.addEventListener('click', () => {
        state.deleted = true;
        dialog.close('delete');
        previewCard.dataset.state = 'is-deleted';
        imageFrame.innerHTML = `
          <div style="display:grid;place-items:center;height:100%;padding:2rem;background:linear-gradient(135deg,#dbeafe,#e0e7ff);text-align:center;">
            <div>
              <p style="margin:0;font-weight:700;font-size:1.15rem;">Image removed</p>
              <p style="margin:0.5rem 0 0;color:#51607a;">This preview is no longer available.</p>
            </div>
          </div>
        `;
        status.textContent = 'Image deleted from your library.';
      });
    }

    render();
  </script>
