  await page.setContent(html, { waitUntil: 'load' });

  const closedByDefault = await page.locator('#confirm-delete-dialog').evaluate(el => !el.open);
  await page.click('#open-delete-dialog');
  const openState = await page.locator('#confirm-delete-dialog').evaluate(el => el.open);
  const activeAfterOpen = await page.evaluate(() => document.activeElement && document.activeElement.textContent.trim());
  await page.keyboard.press('Escape');
  const closedAfterEsc = await page.locator('#confirm-delete-dialog').evaluate(el => !el.open);
  const focusAfterEsc = await page.evaluate(() => document.activeElement && document.activeElement.id);
  await page.click('#open-delete-dialog');
  await page.click('[data-dialog-confirm]');
  const statusText = await page.locator('#status').textContent();
  const focusAfterDelete = await page.evaluate(() => document.activeElement && document.activeElement.id);

  const result = { closedByDefault, openState, activeAfterOpen, closedAfterEsc, focusAfterEsc, statusText, focusAfterDelete };
  console.log(JSON.stringify(result, null, 2));
  await browser.close();
})();
